-- db/seed/funders/axis_bank_disclosures.sql
-- GENERATED from seed/data/funders/axis-bank-statutory-disclosures.json. Edit the JSON.
-- Axis Bank statutory disclosures: CSR obligation and spend from the Board's report
-- annexure, BRSR spend in aspirational districts (per state, with the districts covered),
-- BRSR beneficiary counts, and partners named in impact assessments.
-- Idempotent. Run after db/seed/funders/axis_bank.sql. Aspirational districts must already
-- exist (db/seed/reference_data.sql); a district that cannot be matched stops the load.

BEGIN;

CREATE OR REPLACE FUNCTION pg_temp.funder(p_slug text) RETURNS bigint LANGUAGE sql STABLE AS
$$ SELECT id FROM funders WHERE slug = p_slug $$;

CREATE OR REPLACE FUNCTION pg_temp.state_id(p_state text) RETURNS bigint LANGUAGE sql STABLE AS $$
  SELECT id FROM locations WHERE kind = 'state'
    AND (lower(name) = lower(p_state) OR EXISTS (SELECT 1 FROM unnest(aliases) a WHERE lower(a) = lower(p_state)))
  ORDER BY id LIMIT 1 $$;

-- Match an aspirational district by any of the printed names, within its state.
CREATE OR REPLACE FUNCTION pg_temp.asp_district(p_state text, p_names text[]) RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE v bigint;
BEGIN
  SELECT l.id INTO v FROM locations l
  JOIN location_designations d ON d.location_id = l.id AND d.designation = 'aspirational_district'
  WHERE l.kind = 'district' AND l.parent_id = pg_temp.state_id(p_state)
    AND (lower(l.name) = ANY (SELECT lower(x) FROM unnest(p_names) x)
         OR EXISTS (SELECT 1 FROM unnest(l.aliases) a WHERE lower(a) = ANY (SELECT lower(x) FROM unnest(p_names) x)))
  ORDER BY l.id LIMIT 1;
  IF v IS NULL THEN
    RAISE EXCEPTION 'Aspirational district not matched: % / %', p_state, p_names;
  END IF;
  RETURN v;
END $$;

