-- BRSR FY2025-26 beneficiaries by theme
INSERT INTO metrics (funder_id, program_id, name, value, unit, period, is_self_reported, source_url, source_name, fetched_at, as_of, document_id)
SELECT pg_temp.funder('axis-bank'), (SELECT id FROM programs WHERE funder_id = pg_temp.funder('axis-bank') AND name = 'Education'), 'Direct beneficiaries (students and teachers) (approximate)', 1600000, 'people', 'FY2025-26', true, 'https://www.axis.bank.in/docs/default-source/business-responsibility-reports/business-responsibility-sustainability-report-for-the-year-2025-26.pdf', 'axis-bank-brsr', TIMESTAMPTZ '2026-09-27', 'FY2025-26', (SELECT id FROM documents WHERE source_url = 'https://www.axis.bank.in/docs/default-source/business-responsibility-reports/business-responsibility-sustainability-report-for-the-year-2025-26.pdf' ORDER BY id LIMIT 1)
WHERE NOT EXISTS (SELECT 1 FROM metrics WHERE funder_id = pg_temp.funder('axis-bank') AND name = 'Direct beneficiaries (students and teachers) (approximate)' AND period = 'FY2025-26' AND source_name = 'axis-bank-brsr' AND program_id IS NOT DISTINCT FROM (SELECT id FROM programs WHERE funder_id = pg_temp.funder('axis-bank') AND name = 'Education'));
